CREATE OR REPLACE FUNCTION public.set_family_timezone(_tz text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_parent() OR NOT public.is_parent_device() THEN RAISE EXCEPTION 'Enter parent password first'; END IF; IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_tz) THEN RAISE EXCEPTION 'unknown time zone'; END IF; INSERT INTO public.family_glow_settings(parent_id,timezone) VALUES(auth.uid(),_tz) ON CONFLICT(parent_id) DO UPDATE SET timezone=EXCLUDED.timezone,updated_at=now(); END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['seasons','units','sessions','activities','activity_versions','printables','image_models','art_styles','game_content','game_stickers','manor_cases','print_formats','print_settings','admin_alerts'] LOOP EXECUTE format('CREATE POLICY "Parent mode admin insert" ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_parent_device())',t); EXECUTE format('CREATE POLICY "Parent mode admin update" ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_parent_device()) WITH CHECK(public.is_parent_device())',t); EXECUTE format('CREATE POLICY "Parent mode admin delete" ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(public.is_parent_device())',t); END LOOP; END; $$;